   "held_by": [
    "validation-decision"
   ],
   "written_by_compiled": [
    "record-assent",
    "withdraw-assent"
   ]
  },
  {
   "component": "actor_position",
   "field": "assent_weight",
   "held_by": [
    "actor-position"
   ],
   "written_by_compiled": []
  }
 ],
 "moves": [
  {
   "kind": "communicate",
   "description": "Deliver one represented information item to its declared recipient.",
   "compiled": true
